<script setup>
import {ref,reactive,onActivated} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {http,allRows} from '../api/http'
import {useDirty} from '../stores/dirty'
const rows=ref([]),total=ref(0),busy=ref(false),employees=ref([]),dialog=ref(false),editing=ref(null),detail=ref(null),saving=ref(false)
const filter=reactive({keyword:'',status:null,guitar_model:'',owner_employee_id:null,page:1,page_size:10})
const defaults=()=>({name:'',guitar_model:'',planned_quantity:1,completed_quantity:0,owner_employee_id:null,participant_ids:[],start_date:'',due_date:'',priority:'medium',notes:''})
const form=reactive(defaults()),resetDirty=useDirty(()=>form,()=>dialog.value)
const statuses={not_started:'待开始',in_progress:'制作中',pending_qc:'待质检',completed:'已完成'}
async function load(){busy.value=true;try{const r=await http.get('/tasks',{params:filter});rows.value=r.data;total.value=r.total;employees.value=await allRows('/employees')}catch{}finally{busy.value=false}}
function open(row){editing.value=row;const data=defaults();if(row)for(const k of Object.keys(data))data[k]=row[k];Object.assign(form,data);dialog.value=true}
async function save(){saving.value=true;try{if(editing.value)await http.patch('/tasks/'+editing.value.id,form);else await http.post('/tasks',form);dialog.value=false;resetDirty();ElMessage.success('任务已保存');load()}catch{}finally{saving.value=false}}
async function transition(row,status){try{await ElMessageBox.confirm(`确认将任务推进至“${statuses[status]}”？`,'任务状态确认',{type:'warning'})}catch{return}try{await http.post(`/tasks/${row.id}/transition`,{status});ElMessage.success('任务状态已更新');load()}catch{}}
async function inspect(row,result){try{const r=await ElMessageBox.prompt(result==='passed'?'请填写质检备注（可留空）':'请填写质检不通过原因','录入质检结果',{inputType:'textarea'});await http.post(`/tasks/${row.id}/inspections`,{result,notes:r.value||null});ElMessage.success(result==='passed'?'质检已通过，可确认完成任务':'质检未通过，任务已退回制作中');load()}catch{}}
async function show(row){try{detail.value=(await http.get('/tasks/'+row.id)).data}catch{}}
onActivated(load)
</script>
<template><div class="page-title"><div><h1>制琴任务管理</h1><p>任务从制作到质检，全程保留多人分配与检查历史。</p></div><el-button type="primary" @click="open(null)">新增制琴任务</el-button></div><el-card shadow="never"><el-form inline class="filters"><el-form-item label="任务名称"><el-input v-model="filter.keyword"/></el-form-item><el-form-item label="型号"><el-input v-model="filter.guitar_model"/></el-form-item><el-form-item label="状态"><el-select v-model="filter.status" clearable><el-option v-for="(label,value) in statuses" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="负责人"><el-select v-model="filter.owner_employee_id" clearable><el-option v-for="e in employees" :key="e.id" :value="e.id" :label="e.name"/></el-select></el-form-item><el-button @click="filter.page=1;load()">查询</el-button><el-button @click="Object.assign(filter,{keyword:'',guitar_model:'',status:null,owner_employee_id:null,page:1});load()">重置</el-button></el-form><el-table v-loading="busy" :data="rows" empty-text="暂无任务"><el-table-column prop="task_code" label="任务编号" width="130"/><el-table-column prop="name" label="任务名称" min-width="170"/><el-table-column prop="guitar_model" label="型号"/><el-table-column prop="owner_name" label="负责人"/><el-table-column label="制作进度" min-width="145"><template #default="{row}"><el-progress :percentage="Math.round(row.completed_quantity/row.planned_quantity*100)"/><small>{{row.completed_quantity}} / {{row.planned_quantity}} 把</small></template></el-table-column><el-table-column label="状态"><template #default="{row}">{{statuses[row.status]}}</template></el-table-column><el-table-column prop="due_date" label="预计完成日期" width="120"/><el-table-column label="操作" min-width="240" fixed="right"><template #default="{row}"><el-button link type="primary" @click="show(row)">详情</el-button><el-button v-if="['not_started','in_progress'].includes(row.status)" link type="primary" @click="open(row)">编辑进度</el-button><el-button v-if="row.status==='not_started'" link type="success" @click="transition(row,'in_progress')">开始制作</el-button><el-button v-if="row.status==='in_progress'" link type="success" @click="transition(row,'pending_qc')">提交质检</el-button><template v-if="row.status==='pending_qc'"><el-button link type="success" @click="inspect(row,'passed')">质检通过</el-button><el-button link type="danger" @click="inspect(row,'failed')">质检不通过</el-button><el-button link type="primary" @click="transition(row,'completed')">确认完成</el-button></template></template></el-table-column></el-table><el-pagination class="pagination" v-model:current-page="filter.page" :page-size="10" :total="total" layout="total,prev,pager,next" @current-change="load"/></el-card><WorkspaceDialog v-model="dialog" :title="editing?'编辑任务进度':'新增制琴任务'" width="700px" destroy-on-close><el-form label-position="top"><div class="form-grid"><el-form-item label="任务名称" required><el-input v-model="form.name" maxlength="50"/></el-form-item><el-form-item label="吉他型号" required><el-input v-model="form.guitar_model" maxlength="50"/></el-form-item><el-form-item label="计划数量" required><el-input-number v-model="form.planned_quantity" :min="1" :max="100000"/></el-form-item><el-form-item label="已完成数量"><el-input-number v-model="form.completed_quantity" :min="0" :max="form.planned_quantity"/></el-form-item><el-form-item label="负责人" required><el-select v-model="form.owner_employee_id"><el-option v-for="e in employees" :key="e.id" :value="e.id" :label="e.name+' · '+e.employee_code"/></el-select></el-form-item><el-form-item label="参与员工"><el-select v-model="form.participant_ids" multiple><el-option v-for="e in employees" :key="e.id" :value="e.id" :label="e.name+' · '+e.employee_code"/></el-select></el-form-item><el-form-item label="开始日期" required><el-date-picker v-model="form.start_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="预计完成日期" required><el-date-picker v-model="form.due_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="优先级"><el-select v-model="form.priority"><el-option label="低" value="low"/><el-option label="中" value="medium"/><el-option label="高" value="high"/></el-select></el-form-item></div><el-form-item label="备注"><el-input v-model="form.notes" type="textarea" maxlength="2000"/></el-form-item><el-button type="primary" :loading="saving" @click="save">保存任务</el-button></el-form></WorkspaceDialog><WorkspaceDialog :model-value="!!detail" title="任务详情与质检历史" width="700px" @close="detail=null"><template v-if="detail"><h3>{{detail.name}}</h3><p>{{detail.guitar_model}} · {{statuses[detail.status]}} · {{detail.completed_quantity}} / {{detail.planned_quantity}} 把</p><p>负责人：{{detail.owner_name}}；参与人：{{detail.participant_names.join('、')||'无'}}</p><p>{{detail.notes||'无备注'}}</p><el-table :data="detail.inspections" empty-text="尚无质检历史"><el-table-column label="质检结果"><template #default="{row}">{{row.result==='passed'?'通过':'不通过'}}</template></el-table-column><el-table-column prop="notes" label="备注"/><el-table-column prop="inspected_at" label="检查时间（UTC）"/></el-table></template></WorkspaceDialog></template>
